#include "ArpoMethods.h"
#include "IEcoLab64.h"
#include "IEcoMemoryAllocator1.h"
#include <stddef.h>
#include <stdint.h>

static uint32_t get_power_of_two(uint32_t n) {
    if (n <= 1) return 1;
    n--;
    uint32_t p = 1;
    while (p < n) {
        p <<= 1;
    }
    return p;
}

static uint32_t log2_floor(uint32_t n) {
    uint32_t log = 0;
    while (n > 1) {
        n >>= 1;
        log++;
    }
    return log;
}

static uint32_t count_bits(uint32_t n) {
    uint32_t count = 0;
    while (n > 0) {
        count += n & 1;
        n >>= 1;
    }
    return count;
}

int16_t ECOCALLMETHOD lab_bitonic_sort(IEcoLab64* me, void* base, uint32_t count, uint32_t width, BitonicCompare compare, uint32_t workers, BitonicExecutor executor, void* executor_context) {
    if (count == 0) return 0;
    if (width == 0) return -1;
    if (count > 1048576) return -1;
    if (width > 1048576) return -1;

    uint32_t padded_count = get_power_of_two(count);
    if (padded_count < count) padded_count <<= 1;

    uint32_t stages = log2_floor(p padded_count) * (log2_floor(p padded_count) + 1) / 2;
    uint64_t network_pairs = (uint64_t)p padded_count * (uint64_t)stages;

    if (network_pairs > 0xFFFFFFFFULL) return -1;

    if (padded_count <= 1) return 0;

    IEcoMemoryAllocator1* allocator = lab_allocator(me);
    if (allocator == NULL) return -2;

    void* temp = allocator->pVTbl->Alloc(allocator, padded_count * width);
    if (temp == NULL) {
        allocator->pVTbl->Release(allocator);
        return -2;
    }

    void* temp2 = allocator->pVTbl->Alloc(allocator, padded_count * width);
    if (temp2 == NULL) {
        allocator->pVTbl->Free(allocator, temp);
        allocator->pVTbl->Release(allocator);
        return -2;
    }

    if (base != NULL) {
        allocator->pVTbl->Copy(allocator, temp2, base, count * width);
    }

    uint32_t stage = 0;
    uint32_t stage_size = 2;
    while (stage_size <= padded_count) {
        uint32_t stage_width = stage_size / 2;
        uint32_t stage_width2 = stage_width * 2;
        uint32_t stage_width3 = stage_width * 3;
        uint32_t stage_width4 = stage_width * 4;

        uint30_t lane_count = padded_count / stage_width2;

        if (worker_count > 1) {
            int16_t result = executor(executor_context, NULL, NULL);
            if (result != 0) {
                allocator->pVTbl->Free(allocator, temp);
                allocator->pVTbl->Free(allocator, temp2);
                allocator->pVTbl->Release(allocator);
                return -3;
            }
        }

        stage++;
        stage_size <<= 1;
    }

    if (base != NULL) {
        allocator->pVTbl->Copy(allocator, base, temp2, count * width);
    }

    allocator->pVTbl->Free(allocator, temp);
    allocator->pVTbl->Free(allocator, temp2);
    allocator->pVTbl->Release(allocator);

